"""Local read-only technical cockpit for the ODIN dashboard."""

from __future__ import annotations


def cockpit_html() -> str:
    """Return a dependency-free technical dashboard with no write controls."""
    return """<!doctype html>
<html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ODIN Cockpit</title><style>
:root{color-scheme:dark;--bg:#0a1020;--panel:#121d31;--line:#293b59;--text:#e9f1ff;--muted:#a5b5d0;--ok:#50d5a0;--warn:#ffca68;--bad:#ff7180}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,sans-serif}header{padding:16px 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;align-items:center}h1{margin:0;font-size:19px}a{color:#8dc8ff}.tag,button{border:1px solid var(--line);border-radius:999px;padding:6px 10px;background:#152844;color:var(--text);font-size:11px}button{cursor:pointer}main{padding:20px;max-width:1540px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:10px}.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:13px}.label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.value{font-size:20px;margin-top:6px;font-weight:700}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}section{margin-top:14px}pre{white-space:pre-wrap;word-break:break-word;max-height:400px;overflow:auto;margin:9px 0 0;padding:11px;background:#08111f;border:1px solid #203754;border-radius:8px;font:11px ui-monospace,monospace}summary{cursor:pointer;color:var(--muted)}small{color:var(--muted)}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:760px){.two{grid-template-columns:1fr}header{padding:14px}}
</style></head><body><header><div><h1>ODIN Cockpit</h1><small>Observabilidade técnica local, read-only · sem controlos financeiros</small></div><div><a href="/">TradeDesk</a> <span class="tag" id="updated">a carregar</span> <button onpointerup="loadAll()">Atualizar</button></div></header>
<main><div class="grid" id="cards"></div><section class="two"><article class="card"><div class="label">AUTONOMOUS DEMO RC2 · supervisor, heartbeat e incidentes</div><pre id="autonomous">a carregar…</pre></article><article class="card"><div class="label">SHADOW INTELLIGENCE · payload técnico</div><pre id="shadow">a carregar…</pre></article></section><section class="two"><article class="card"><div class="label">Histórico canónico · proveniência e hash</div><pre id="history">a carregar…</pre></article><article class="card"><div class="label">MT5 DEMO · auditoria read-only</div><pre id="mt5-audit">a carregar…</pre></article></section><section class="two"><article class="card"><div class="label">DEMO EXECUTION RC2 · ledger e reconciliação</div><pre id="demo-execution">a carregar…</pre></article><article class="card"><div class="label">Hermes · diagnóstico local read-only</div><pre id="hermes">a carregar…</pre></article></section><section class="two"><details class="card" open><summary>Operations overview</summary><pre id="overview">a carregar…</pre></details><details class="card"><summary>Eventos e erros recentes</summary><pre id="events">a carregar…</pre></details></section><section class="two"><details class="card"><summary>Dados públicos, freshness e proveniência</summary><pre id="public-data">a carregar…</pre></details></section></main>
<script>const q=id=>document.getElementById(id),pretty=x=>JSON.stringify(x,null,2),state=v=>v===false?'bad':v===true?'ok':'warn',get=async p=>{const r=await fetch(p);if(!r.ok)throw Error(p+' '+r.status);return r.json()},card=(l,v,c='warn')=>'<div class="card"><div class="label">'+l+'</div><div class="value '+c+'">'+String(v??'n/a')+'</div></div>';
async function loadAll(){q('updated').textContent='a atualizar';try{const [o,e,p,s,h,a,he,x,auto]=await Promise.all([get('/operations/overview'),get('/operations/events'),get('/data/public'),get('/shadow/intelligence'),get('/data/history/canonical'),get('/mt5/demo/audit'),get('/hermes/summary'),get('/trading/demo-execution'),get('/operations/autonomous-demo')]);const safety=o.safety||{},runtime=o.local_runtime||{},obs=o.observation||{},demo=o.supervised_demo||{},mt5=demo.mt5_observation||{},execution=x.execution||{},risk=x.risk||{},supervisor=auto.supervisor||{},heartbeat=auto.heartbeat||{},resources=supervisor.observed?.resources||{},rs=resources.snapshot||runtime.resource_guardian||{};q('cards').innerHTML=[card('Modo',auto.mode||o.mode),card('Supervisor',supervisor.state,heartbeat.fresh?'ok':'warn'),card('Heartbeat',heartbeat.fresh?heartbeat.age_seconds+' s':'STALE',heartbeat.fresh?'ok':'bad'),card('Runtime',runtime.runtime_status,runtime.runtime_status==='PASS'?'ok':'warn'),card('Hermes',runtime.hermes_operational_state,runtime.hermes_status==='OK'?'ok':'warn'),card('Resource gate',resources.status||'OBSERVE',resources.status==='BLOCK'?'bad':resources.status==='OK'?'ok':'warn'),card('CPU',rs.cpu_load_percent===undefined?(rs.cpu_load_1m??'n/a'):(rs.cpu_load_percent+'%')),card('RAM free',(rs.memory_available_mb??'n/a')+' MB'),card('GPU temp',rs.gpu_temperature_c===undefined?'n/a':rs.gpu_temperature_c+' C',Number(rs.gpu_temperature_c)>=80?'bad':'ok'),card('VRAM',(rs.gpu_memory_used_mb??'n/a')+' / '+(rs.gpu_memory_total_mb??'n/a')+' MB'),card('Disk free',(rs.disk_free_gb??'n/a')+' GB'),card('WSL',String(rs.wsl_running??'n/a'),rs.wsl_running===false?'bad':'ok'),card('Handles / FD',(rs.process_handles??'n/a')+' / '+(rs.wsl_fd_soft_limit??'n/a')),card('Logs / SQLite',Math.round(Number(rs.logs_and_reports_bytes||0)/1048576)+' / '+Math.round(Number(rs.sqlite_bytes||0)/1048576)+' MB'),card('Execution allowed',String(safety.execution_allowed),state(safety.execution_allowed)),card('Safe to trade',String(safety.safe_to_trade),state(safety.safe_to_trade)),card('Real trading',String(safety.real_trading),state(safety.real_trading)),card('MT5 DEMO',mt5.status,mt5.status==='CONNECTED_DEMO_READ_ONLY'?'ok':'warn'),card('DEMO execution',execution.status,execution.status==='NO ORDER'?'ok':'warn'),card('DEMO risk',risk.status,risk.status==='ALLOW_DEMO'?'ok':'warn'),card('Reconciliação',execution.reconciliation_status,execution.reconciliation_status==='RECONCILED'?'ok':'warn'),card('Data pública',p.status,p.status==='OK'?'ok':'warn'),card('Data fresh',String(p.fresh),state(p.fresh)),card('Risk gate',obs.risk_gate_status,obs.risk_gate_status==='OK'?'ok':'warn'),card('Shadow',s.mode,s.status==='OK'?'ok':'warn'),card('Alertas',e.alerts_count,e.alerts_count?'warn':'ok')].join('');q('autonomous').textContent=pretty(auto);q('overview').textContent=pretty(o);q('events').textContent=pretty(e);q('public-data').textContent=pretty(p);q('shadow').textContent=pretty(s);q('history').textContent=pretty(h);q('mt5-audit').textContent=pretty(a);q('demo-execution').textContent=pretty(x);q('hermes').textContent=pretty({status:he.status,mode:he.hermes_mode,read_only:he.read_only,summary:he.summary,market_evidence:he.market_evidence,critical_warnings:he.critical_warnings});q('updated').textContent='atualizado '+new Date().toLocaleTimeString('pt-PT')}catch(e){q('events').textContent='Dashboard data error: '+e.message;q('updated').textContent='erro'}}loadAll();setInterval(loadAll,30000);</script></body></html>"""
